  public static void Text(Graphics g,string text,Font font,Rectangle bounds,Color color,ContentAlignment align){g.TextRenderingHint=TextRenderingHint.SingleBitPerPixelGridFit;using(var format=new StringFormat()){format.Alignment=align==ContentAlignment.MiddleCenter?StringAlignment.Center:align==ContentAlignment.MiddleRight?StringAlignment.Far:StringAlignment.Near;format.LineAlignment=StringAlignment.Center;format.Trimming=StringTrimming.EllipsisCharacter;format.FormatFlags=StringFormatFlags.NoWrap;using(var brush=new SolidBrush(color))g.DrawString(text,font,brush,bounds,format);}}
  public static Label Label(string text,int height=26){return new PixelLabel{Text=text,AutoSize=false,Height=height,ForeColor=Ink,Font=UI(),TextAlign=ContentAlignment.MiddleLeft,Dock=DockStyle.Top};}
  public static ComboBox Combo(IEnumerable<string> entries,string value){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Font=new Font("맑은 고딕",10),Dock=DockStyle.Fill};c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=27;c.DrawItem+=(s,e)=>{e.Graphics.FillRectangle((e.State&DrawItemState.Selected)!=0?Brushes.Black:Brushes.White,e.Bounds);if(e.Index>=0)using(var font=UI())Theme.Text(e.Graphics,c.Items[e.Index].ToString(),font,e.Bounds,(e.State&DrawItemState.Selected)!=0?Color.White:Color.Black,ContentAlignment.MiddleLeft);};c.Items.AddRange(entries.Cast<object>().ToArray());c.SelectedItem=value;if(c.SelectedIndex<0&&c.Items.Count>0)c.SelectedIndex=0;return c;}
  public static NumericUpDown Number(decimal value,decimal min,decimal max,int decimals=0){return new NumericUpDown{Minimum=min,Maximum=max,Value=Math.Min(max,Math.Max(min,value)),DecimalPlaces=decimals,Increment=decimals>0?.1m:1,Font=new Font("맑은 고딕",10),Dock=DockStyle.Fill};}
  public static TableLayoutPanel Table(int cols=2){var t=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=cols,Padding=new Padding(15)};t.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,145));for(int i=1;i<cols;i++)t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/(cols-1)));return t;}
  public static void Row(TableLayoutPanel t,string label,Control c){int row=t.RowCount++;t.RowStyles.Add(new RowStyle(SizeType.Absolute,42));t.Controls.Add(Label(label),0,row);t.Controls.Add(c,1,row);}
 }
 static class Fonts {
  static List<IntPtr> memory=new List<IntPtr>();static List<PrivateFontCollection> collections=new List<PrivateFontCollection>();
  [DllImport("gdi32.dll")]static extern IntPtr AddFontMemResourceEx(IntPtr data,uint size,IntPtr reserved,ref uint count);
  public static FontFamily AA,System;
  public static void Load(){AA=LoadOne("HeadKasen.ttf");System=LoadOne("pokemon-bw.otf");}
  static FontFamily LoadOne(string name){var bytes=Resource.Bytes(name);var ptr=Marshal.AllocCoTaskMem(bytes.Length);Marshal.Copy(bytes,0,ptr,bytes.Length);memory.Add(ptr);uint count=0;AddFontMemResourceEx(ptr,(uint)bytes.Length,IntPtr.Zero,ref count);var fonts=new PrivateFontCollection();fonts.AddMemoryFont(ptr,bytes.Length);collections.Add(fonts);return fonts.Families[0];}
 }
