 class AAView:Panel {
  string art="";public float TextSize=15;public bool Fit=true;
  public string Art {get{return art;}set{art=value??"";Invalidate();}}
  public AAView(){DoubleBuffered=true;BackColor=Color.White;AutoScroll=true;}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.TextRenderingHint=TextRenderingHint.AntiAliasGridFit;string[] lines=art.Replace("\r","").Split('\n');if(string.IsNullOrWhiteSpace(art)){TextRenderer.DrawText(e.Graphics,"AA를 붙여 넣어 주세요",Theme.UI(),ClientRectangle,Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);return;}using(var f=new Font(Fonts.AA,TextSize,FontStyle.Regular,GraphicsUnit.Pixel)){var format=(StringFormat)StringFormat.GenericTypographic.Clone();format.FormatFlags|=StringFormatFlags.MeasureTrailingSpaces|StringFormatFlags.NoWrap;float width=lines.Max(s=>e.Graphics.MeasureString(s,f,int.MaxValue,format).Width),height=lines.Length*(TextSize+1);float scale=Fit?Math.Min(1,Math.Min((ClientSize.Width-18)/Math.Max(1,width),(ClientSize.Height-18)/Math.Max(1,height))):1;AutoScrollMinSize=Fit?Size.Empty:new Size((int)width+20,(int)height+20);float x=Fit?Math.Max(8,(ClientSize.Width-width*scale)/2):8+AutoScrollPosition.X,y=Fit?Math.Max(8,(ClientSize.Height-height*scale)/2):8+AutoScrollPosition.Y;e.Graphics.TranslateTransform(x,y);e.Graphics.ScaleTransform(scale,scale);for(int i=0;i<lines.Length;i++)e.Graphics.DrawString(lines[i],f,Brushes.Black,new PointF(0,i*(TextSize+1)),format);format.Dispose();}}
 }
 class PokemonCard:Card {
