  public PokemonCard(int side){Title=new PixelLabel{Font=Theme.UI(15,FontStyle.Bold),ForeColor=Theme.Ink,BackColor=Color.White};Meta=new PixelLabel{Font=Theme.UI(8),ForeColor=Theme.Muted,BackColor=Color.White};HP=new PixelLabel{Font=Theme.UI(8),TextAlign=ContentAlignment.MiddleRight,ForeColor=Theme.Muted,BackColor=Color.White};Edit=new FlatButton{Text="편집",Font=Theme.UI(8)};State=new FlatButton{Text="상태",Font=Theme.UI(8)};StateLine=new PixelLabel{Font=Theme.UI(8),BackColor=Color.White};Art=new AAView();Controls.AddRange(new Control[]{Title,Meta,HP,Edit,State,StateLine,Art});}
  protected override void OnResize(EventArgs e){base.OnResize(e);if(Title==null)return;Title.SetBounds(23,20,Width-165,30);State.SetBounds(Width-136,20,53,30);Edit.SetBounds(Width-77,20,53,30);Meta.SetBounds(24,53,Width-160,22);HP.SetBounds(Width-158,53,133,22);StateLine.SetBounds(25,103,Width-52,25);Art.SetBounds(18,137,Width-40,Height-164);}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int x=25,y=86,w=Width-54;e.Graphics.DrawRectangle(Pens.Black,x,y,w,12);int n=(w-4)/6;for(int i=0;i<n;i++)if(i<(int)Math.Ceiling(n*hpRatio))e.Graphics.FillRectangle(Brushes.Black,x+3+i*6,y+3,4,7);}
  public void ShowFighter(Fighter f,int max,int side){Title.Text=f.Data.name;Meta.Text="TEAM "+(side+1)+"   ·   Lv. "+f.Data.level+"   ·   "+string.Join(" / ",f.Data.types);HP.Text="HP  "+f.HP+" / "+max;hpRatio=max>0?(double)f.HP/max:0;Art.Art=f.AA;Invalidate();}
 }
 class MoveCard:Card {
  public FlatButton[] Buttons=new FlatButton[4];public event Action<int> SelectedMove;
  public MoveCard(){for(int i=0;i<4;i++){int k=i;Buttons[i]=new FlatButton{Font=Theme.UI(10,FontStyle.Bold)};Buttons[i].Click+=(s,e)=>{if(SelectedMove!=null)SelectedMove(k);};Controls.Add(Buttons[i]);}}
  protected override void OnResize(EventArgs e){base.OnResize(e);int w=(Width-38)/2,h=(Height-38)/2;for(int i=0;i<4;i++)if(Buttons[i]!=null)Buttons[i].SetBounds(14+(i%2)*(w+10),14+(i/2)*(h+10),w,h);}
  public void RefreshMoves(Fighter f,Database db){for(int i=0;i<4;i++){string name=i<f.Moves.Length?f.Moves[i]:"";var m=db.moves.FirstOrDefault(x=>x.name==name);Buttons[i].Text=name.Length>0?name:"—";Buttons[i].Subtext=m==null?"기술 편집에서 등록":string.Join("/",m.types)+" · "+m.category+" · "+(m.power>0?m.power.ToString():"—");Buttons[i].Enabled=m!=null;Buttons[i].Selected=f.Selected==i;Buttons[i].Invalidate();}}
 }
 class TurnSelection {public string Form="",Order="";public int SwitchIndex=-1;public TurnSelection Copy(){return new TurnSelection{Form=Form,Order=Order,SwitchIndex=SwitchIndex};}}
 static class DirectiveRules {
  static readonly string[] Forms={"물러나","피해라","돌아와","버텨라","맞춰라"};
