  public static string Label(TurnSelection v){string action=v.SwitchIndex>=0?"교대":"기술";return action+" · 4식 "+(v.Form.Length>0?v.Form:"—")+" · 지령 "+(v.Order.Length>0?v.Order:"—");}
 }
 class DirectiveForm:Form {
  public TurnSelection Value;ComboBox action,target,form,order;List<Fighter> reserves;TrainerBattleState state;TrainerRecord trainer;bool loading;
  public DirectiveForm(TrainerRecord source,TrainerBattleState used,List<Fighter> team,TurnSelection input){trainer=source;state=used;reserves=team;Value=input.Copy();Text="행동 / 4식 / 지령 선언";Size=new Size(590,360);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();var table=Theme.Table();action=Theme.Combo(new[]{"기술 사용","교대"},Value.SwitchIndex>=0?"교대":"기술 사용");target=Theme.Combo(new[]{"선택하세요"}.Concat(reserves.Select(x=>x.Data.name)),Value.SwitchIndex>=0&&Value.SwitchIndex<reserves.Count?reserves[Value.SwitchIndex].Data.name:"선택하세요");form=Theme.Combo(new[]{"사용 안 함"},"사용 안 함");order=Theme.Combo(new[]{"사용 안 함"},"사용 안 함");Theme.Row(table,"이번 행동",action);Theme.Row(table,"교대 대상",target);Theme.Row(table,"4식 (턴당 1회)",form);Theme.Row(table,"지령 (턴당 1개)",order);var note=Theme.Label(trainer==null?"트레이너를 적용하면 그 트레이너의 4식·지령이 여기에 나타납니다.":"모두 선택 사항이며, 각 항목은 1시합 1회입니다. 『돌아와!』는 교대와 함께 선언합니다.",48);note.ForeColor=Theme.Muted;Theme.Row(table,"규칙",note);var foot=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=62,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(12)};var apply=new FlatButton{Text="선택",Primary=true,Size=new Size(95,36)};var cancel=new FlatButton{Text="취소",Size=new Size(85,36),DialogResult=DialogResult.Cancel};foot.Controls.AddRange(new Control[]{apply,cancel});Controls.Add(table);Controls.Add(foot);action.SelectedIndexChanged+=(s,e)=>FillChoices();apply.Click+=(s,e)=>Apply();FillChoices();}
  IEnumerable<string> EnabledNames(){return (trainer==null||trainer.potentials==null?Enumerable.Empty<PotentialRecord>():trainer.potentials.Where(x=>x.enabled&&x.slot=="지령"&&x.name.Length>0)).Select(x=>x.name);}
  void FillChoices(){if(loading)return;loading=true;bool switching=(string)action.SelectedItem=="교대";string oldForm=Value.Form,oldOrder=Value.Order;var forms=EnabledNames().Where(DirectiveRules.IsForm).Where(x=>!state.UsedForms.Contains(x)).Where(x=>switching?x.Contains("돌아와"):!x.Contains("돌아와")).Distinct().ToArray();form.Items.Clear();form.Items.Add("사용 안 함");form.Items.AddRange(forms.Cast<object>().ToArray());form.SelectedItem=forms.Contains(oldForm)?oldForm:"사용 안 함";var orders=EnabledNames().Where(x=>!DirectiveRules.IsForm(x)&&!state.UsedOrders.Contains(x)).Distinct().ToArray();order.Items.Clear();order.Items.Add("사용 안 함");if(!switching)order.Items.AddRange(orders.Cast<object>().ToArray());order.SelectedItem=!switching&&orders.Contains(oldOrder)?oldOrder:"사용 안 함";target.Enabled=switching;form.Enabled=forms.Length>0;order.Enabled=!switching&&orders.Length>0;loading=false;}
  void Apply(){bool switching=(string)action.SelectedItem=="교대";int selected=target.SelectedIndex-1;if(switching&&selected<0){MessageBox.Show(this,"교대할 포켓몬을 선택하세요.");return;}string selectedForm=(string)form.SelectedItem,selectedOrder=(string)order.SelectedItem;Value=new TurnSelection{SwitchIndex=switching?selected:-1,Form=selectedForm=="사용 안 함"?"":selectedForm,Order=selectedOrder=="사용 안 함"?"":selectedOrder};DialogResult=DialogResult.OK;Close();}
 }
 class Snapshot {public Rules Rules;public Fighter[] Fighters;public List<Fighter>[] Reserves;public TrainerBattleState[] Trainers;public TurnSelection[] Selections;public int Turn;public string Log;}
 class MainForm:Form {
  readonly Database db;public Fighter[] Fighters;public Rules Rules=new Rules();int turn=1;Random random=new Random();Stack<Snapshot> undo=new Stack<Snapshot>();string log="";
  TrainerRecord[] trainers=new TrainerRecord[2];TrainerBattleState[] trainerStates={new TrainerBattleState(),new TrainerBattleState()};TurnSelection[] selections={new TurnSelection(),new TurnSelection()};List<Fighter>[] reserves={new List<Fighter>(),new List<Fighter>()};
  PokemonCard[] cards=new PokemonCard[2];MoveCard[] moveCards=new MoveCard[2];FlatButton[] directiveButtons=new FlatButton[2];FlatButton calculate,settings,results,reset,back,guide,teamEditor;Label brand,turnLabel,status,fieldLabel;ToolTip hints=new ToolTip{AutoPopDelay=15000,InitialDelay=300};ResultForm resultForm;DataEditorForm dataEditorForm;
  public MainForm(Database database){db=database;Text="AA BATTLE · 지령 시스템 빌드 0.6";ClientSize=new Size(1220,780);MinimumSize=new Size(940,670);StartPosition=FormStartPosition.CenterScreen;BackColor=Theme.Paper;Font=Theme.UI();AutoScaleMode=AutoScaleMode.Dpi;DoubleBuffered=true;
   Fighters=new[]{new Fighter(db.pokemon.First(p=>p.name=="선데이")),new Fighter(db.pokemon.First(p=>p.name=="잭 한마"))};var arts=new JavaScriptSerializer().Deserialize<string[]>(Resource.Text("aa.json"));Fighters[0].AA=ExtractArt(arts[4]);Fighters[1].AA=ExtractArt(arts[3]);
   for(int i=0;i<2;i++){var existing=Fighters[i].Moves.Concat(i==0?new[]{"에어슬래시","10만볼트","방어"}:new[]{"독찌르기","지진","방어"}).Distinct().Where(n=>db.moves.Any(m=>m.name==n)).Take(4).ToArray();Fighters[i].Moves=existing;}
