  void Save(){undo.Push(new Snapshot{Fighters=Fighters.Select(f=>f.Copy()).ToArray(),Reserves=reserves.Select(x=>x.Select(f=>f.Copy()).ToList()).ToArray(),Trainers=trainerStates.Select(x=>x.Copy()).ToArray(),Selections=selections.Select(x=>x.Copy()).ToArray(),Rules=Rules.Copy(),Turn=turn,Log=log});}
  void Undo(){if(undo.Count==0)return;var s=undo.Pop();Fighters=s.Fighters;reserves=s.Reserves;trainerStates=s.Trainers;selections=s.Selections;Rules=s.Rules;turn=s.Turn;log=s.Log;RefreshView();}
  void ResetFighter(Fighter f,bool heal){f.Stages=new int[6];f.AccuracyStage=f.EvasionStage=0;f.AccuracyMultiplier=f.EvasionMultiplier=1;f.Multipliers=new[]{1d,1d,1d,1d,1d,1d};f.Status="정상";f.Conditions=new ConditionState();if(heal)f.HP=Engine.Stats(f,f.Data.level,new Rules())[0];}
  void Bench(Fighter f){f.Stages=new int[6];f.AccuracyStage=f.EvasionStage=0;f.AccuracyMultiplier=f.EvasionMultiplier=1;f.Multipliers=new[]{1d,1d,1d,1d,1d,1d};f.Conditions.Confusion=f.Conditions.Taunt=f.Conditions.Substitute=f.Conditions.ProtectChain=0;f.Conditions.Protect=f.Conditions.Flinch=f.Conditions.Seed=f.Conditions.Curse=f.Conditions.Ingrain=false;}
