  void Edit(int side){using(var dialog=new FighterForm(db,Fighters[side],Fighters[1-side].Data.level,Rules)){if(dialog.ShowDialog(this)==DialogResult.OK){Save();Fighters[side]=dialog.Value;RefreshView();}}}
  void EditConditions(int side){using(var dialog=new ConditionsForm(db,Fighters[side],Fighters[1-side],Rules)){if(dialog.ShowDialog(this)==DialogResult.OK){Save();Fighters[side]=dialog.Value;RefreshView();}}}
  void Battle(){if(Fighters.Any(f=>f.HP<=0))return;var old=Fighters.Select(x=>x.Copy()).ToArray();var commands=new BattleCommand[2];var rangeLines=new List<string>();for(int i=0;i<2;i++){var pick=selections[i];if(pick.SwitchIndex>=0){if(pick.SwitchIndex>=reserves[i].Count){MessageBox.Show(this,"교대 대상을 다시 선택하세요.");return;}commands[i]=new BattleCommand{SwitchIn=reserves[i][pick.SwitchIndex],Form=pick.Form,Order=pick.Order};rangeLines.Add(Fighters[i].Data.name+" · 교대 → "+commands[i].SwitchIn.Data.name);}else{var m=db.moves.First(x=>x.name==Fighters[i].Moves[Math.Min(Fighters[i].Selected,Fighters[i].Moves.Length-1)]);commands[i]=new BattleCommand{Move=m,Form=pick.Form,Order=pick.Order};var d=Engine.Calculate(db,Fighters[i],Fighters[1-i],m,Rules);rangeLines.Add(Fighters[i].Data.name+" · "+m.name+"   "+(d.Supported?d.Min+" – "+d.Max+"  (자속 ×"+d.Stab+", 상성 ×"+d.Type+")":(Mechanics.KnownMove(m)&&m.name!="날개쉬기"?"상태 기술":"수동 판정")));}}Save();try{var result=Engine.Resolve(db,Fighters,commands,Rules,trainerStates,random.NextDouble);for(int i=0;i<2;i++)if(result.Switched[i]){reserves[i].RemoveAt(selections[i].SwitchIndex);var outgoing=old[i];Bench(outgoing);reserves[i].Add(outgoing);}log="TURN "+turn+"\r\n"+string.Join("\r\n",rangeLines)+"\r\n\r\n"+string.Join("\r\n",result.Log)+"\r\n\r\n────────────────────\r\n\r\n"+log;Fighters=result.Fighters;Rules=result.Rules;trainerStates=result.Trainers;selections=new[]{new TurnSelection(),new TurnSelection()};turn++;RefreshView();ShowResults();}catch(Exception ex){undo.Pop();MessageBox.Show(this,ex.Message,"지시 확인",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
  public void RefreshView(){for(int i=0;i<2;i++){cards[i].ShowFighter(Fighters[i],Engine.Stats(Fighters[i],Fighters[1-i].Data.level,Rules)[0],i);moveCards[i].RefreshMoves(Fighters[i],db);directiveButtons[i].Text=DirectiveRules.Label(selections[i]);directiveButtons[i].Subtext=(trainers[i]==null?"트레이너 미적용":(trainers[i].name.Length>0?trainers[i].name:"이름 없는 트레이너"))+" · 대기 "+reserves[i].Count;cards[i].StateLine.Text=RuleBook.Summary(Fighters[i],Fighters[1-i],Rules);hints.SetToolTip(cards[i].StateLine,cards[i].StateLine.Text);hints.SetToolTip(directiveButtons[i],trainers[i]==null?"팀 편집에서 트레이너를 적용하면 4식·지령을 선택할 수 있습니다.":"4식과 지령은 선택 사항이며 각 항목은 1시합 1회입니다.");for(int j=0;j<Fighters[i].Moves.Length;j++){var m=db.moves.FirstOrDefault(v=>v.name==Fighters[i].Moves[j]);if(m==null)continue;string block=Mechanics.TargetsOpponent(m)?Mechanics.Block(db,Fighters[i],Fighters[1-i],m,Rules):"";var button=moveCards[i].Buttons[j];button.Subtext=string.Join("/",m.types)+" / "+(block.Length>0?"무효":m.category=="변화"?(Mechanics.KnownMove(m)&&m.name!="날개쉬기"?"상태 적용":"수동 판정"):"상성 ×"+Mechanics.TypeEffect(db,Fighters[i],Fighters[1-i],m,Rules));hints.SetToolTip(button,(block.Length>0?block+"\n":"")+m.effect+"\n등록된 효과 외에는 수동 판정입니다.");button.Invalidate();}}fieldLabel.Text=RuleBook.Field(Rules,Fighters);turnLabel.Text="TURN  "+turn.ToString("00");calculate.Enabled=Fighters.All(f=>f.HP>0);back.Enabled=undo.Count>0;status.Text=Fighters.Any(f=>f.HP<=0)?"포켓몬이 쓰러졌습니다. 교대하거나 초기화하세요.":"기술을 선택하고 필요하면 4식·지령을 선언한 뒤 배틀 !";if(resultForm!=null&&!resultForm.IsDisposed)resultForm.SetLog(log);}
  void ShowResults(){if(resultForm==null||resultForm.IsDisposed)resultForm=new ResultForm();resultForm.SetLog(log);if(!resultForm.Visible)resultForm.Show(this);resultForm.Activate();}
  void ShowTeamEditor(){if(dataEditorForm==null||dataEditorForm.IsDisposed){dataEditorForm=new DataEditorForm(LoadFromEditor,LoadTrainerFromEditor);dataEditorForm.FormClosed+=(s,e)=>dataEditorForm=null;dataEditorForm.Show(this);}else dataEditorForm.Activate();}
  void LoadFromEditor(PokemonRecord source,int side){string warning;var data=EditorBridge.ToPokemon(source,db,out warning);Save();var fighter=new Fighter(data);fighter.AA=source.asciiArt;if(Fighters[side].Data.name!=data.name){if(reserves[side].Count>=5)throw new Exception("한 팀에는 대기 포켓몬을 5체까지만 둘 수 있습니다.");reserves[side].RemoveAll(x=>x.Data.name==data.name);reserves[side].Add(Fighters[side].Copy());}Fighters[side]=fighter;selections[side]=new TurnSelection();log="팀 편집기에서 "+data.name+"을 "+(side==0?"왼쪽":"오른쪽")+" 배틀 슬롯에 불러왔습니다."+(warning.Length>0?"\r\n"+warning:"")+"\r\n\r\n"+log;RefreshView();status.Text=data.name+" → "+(side==0?"왼쪽":"오른쪽")+" 슬롯 적용 완료 · 이전 포켓몬은 대기"+(warning.Length>0?" (일부 항목 제외)":"");}
  void LoadTrainerFromEditor(TrainerRecord source,int side){Save();string json=new JavaScriptSerializer().Serialize(source);trainers[side]=new JavaScriptSerializer().Deserialize<TrainerRecord>(json);trainerStates[side]=new TrainerBattleState();selections[side]=new TurnSelection();log=(source.name.Length>0?source.name:"이름 없는 트레이너")+"를 TRAINER "+(side+1)+"에 적용했습니다. 지령 사용 이력이 초기화됩니다.\r\n\r\n"+log;RefreshView();}
  public void Smoke(){var old=Fighters[0].HP;var savedRules=Rules.Copy();Rules.Weather="비";Rules.WeatherTurns=3;Fighters[0].Conditions.Reflect=3;Battle();if(turn!=2||log.Length==0)throw new Exception("Turn UI failed");Undo();if(turn!=1||Fighters[0].HP!=old||Rules.WeatherTurns!=3||Fighters[0].Conditions.Reflect!=3)throw new Exception("Undo UI failed");Rules=savedRules;Fighters[0].Conditions.Reflect=0;RefreshView();if(resultForm!=null)resultForm.Close();using(var f=new FighterForm(db,Fighters[0],Fighters[1].Data.level,Rules)){f.CreateControl();}using(var f=new RulesForm(Rules)){f.CreateControl();}using(var f=new DataEditorForm()){f.CreateControl();}}
 }
 class LogView:Panel {
  string content="";public LogView(){DoubleBuffered=true;AutoScroll=true;BackColor=Color.White;}
  public void SetLog(string log){content=log;AutoScrollPosition=Point.Empty;Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.TextRenderingHint=TextRenderingHint.SingleBitPerPixelGridFit;float y=AutoScrollPosition.Y;int width=Math.Max(50,ClientSize.Width-22);using(var f=new Font(Fonts.System,20,FontStyle.Regular,GraphicsUnit.Pixel)){foreach(string line in content.Replace("\r","").Split('\n')){float height=Math.Max(27,e.Graphics.MeasureString(line.Length==0?" ":line,f,width).Height+5);using(var brush=new SolidBrush(Theme.Ink))e.Graphics.DrawString(line,f,brush,new RectangleF(2,y,width,height));y+=height;}}AutoScrollMinSize=new Size(0,(int)y-AutoScrollPosition.Y+10);}
 }
